begin;
with j as (select * from jsonb_to_recordset($law7d0006$[{"code_id":"APK_RF","article_number":"245.1","version_date":"2002-07-24","article_text":"1. Решения иностранных судов и иностранные арбитражные решения, не требующие принудительного исполнения, признаются в Российской Федерации, если их признание предусмотрено международным договором Российской Федерации и федеральным законом.\n\n2. Решения иностранных судов и иностранные арбитражные решения, не требующие принудительного исполнения, признаются в Российской Федерации без какого-либо дальнейшего производства, если со стороны заинтересованного лица не поступят возражения относительно этого.\n\n3. Заинтересованное лицо в течение одного месяца после того, как ему стало известно о решении иностранного суда или об иностранном арбитражном решении, может заявить возражения относительно признания этого решения в арбитражный суд субъекта Российской Федерации по месту нахождения или месту жительства заинтересованного лица либо месту нахождения его имущества, а если заинтересованное лицо не имеет места жительства, места нахождения или имущества в Российской Федерации, в Арбитражный суд города Москвы.\n\n1) наименование арбитражного суда, в который подается заявление;\n\n2) наименование и место нахождения иностранного суда либо состав третейского суда или международного коммерческого арбитража, его место нахождения;\n\n3) наименование заинтересованного лица, его место нахождения или место жительства;\n\n4) сведения о решении иностранного суда или об иностранном арбитражном решении, возражения против признания которых заявляет заинтересованное лицо;\n\n5) ходатайство заинтересованного лица об отказе в признании решения иностранного суда или иностранного арбитражного решения с приведением оснований для отказа в таком признании, а также с обоснованием нарушения указанным решением прав и законных интересов заинтересованного лица в сфере предпринимательской и иной экономической деятельности в Российской Федерации;\n\n6) перечень прилагаемых документов.\n\n1) удостоверенная надлежащим образом копия решения иностранного суда или иностранного арбитражного решения, возражения против признания которых заявляет заинтересованное лицо;\n\n2) подлинное соглашение о третейском разбирательстве или его надлежащим образом заверенная копия, если заинтересованным лицом заявляются возражения против признания иностранного арбитражного решения;\n\n3) доверенность или иной документ, удостоверенные надлежащим образом и подтверждающие полномочия лица, подписавшего заявление в арбитражный суд;\n\n4) документ об уплате государственной пошлины за подачу заявления в размере, предусмотренном федеральным законом для оплаты искового заявления неимущественного характера;\n\n5) заверенный надлежащим образом перевод на русский язык документов, указанных в пунктах 1 - 3 настоящей части.\n\n(Дополнение статьей - Федеральный закон от 29.12.2015 № 409-ФЗ)","article_title":"Статья 245.1. Решения иностранных судов и иностранные арбитражные решения, не требующие принудительного исполнения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4e0d440a65ed6970189f383284fce86cc65d166f0026e43a2388034a9c71102a"},{"code_id":"APK_RF","article_number":"246","version_date":"2002-07-24","article_text":"1. Принудительное исполнение решения иностранного суда или иностранного арбитражного решения производится на основании исполнительного листа, выдаваемого арбитражным судом, вынесшим определение о признании и приведении в исполнение решения иностранного суда или иностранного арбитражного решения, в порядке, предусмотренном настоящим Кодексом и федеральным законом об исполнительном производстве.\n\n2. Решение иностранного суда или иностранное арбитражное решение может быть предъявлено к принудительному исполнению в срок, не превышающий трех лет со дня вступления его в законную силу. В случае пропуска указанного срока он может быть восстановлен арбитражным судом по ходатайству взыскателя по правилам, предусмотренным главой 10 настоящего Кодекса.\n\nРАЗДЕЛ V. ПРОИЗВОДСТВО ПО ДЕЛАМ С УЧАСТИЕМ ИНОСТРАННЫХ ЛИЦ","article_title":"Статья 246. Принудительное исполнение решения иностранного суда или иностранного арбитражного решения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"fd1cd33d2887283fbe8a3d9a42bc43f22b4612e7147b191262766073bf5db107"},{"code_id":"APK_RF","article_number":"247","version_date":"2002-07-24","article_text":"1. Арбитражные суды в Российской Федерации рассматривают дела по экономическим спорам и другие дела, связанные с осуществлением предпринимательской и иной экономической деятельности, с участием иностранных организаций, международных организаций, иностранных граждан, лиц без гражданства, осуществляющих предпринимательскую и иную экономическую деятельность (далее - иностранные лица), в случае, если:\n\n1) ответчик находится или проживает на территории Российской Федерации либо на территории Российской Федерации находится имущество ответчика;\n\n2) орган управления, филиал или представительство иностранного лица находится на территории Российской Федерации;\n\n3) спор возник из договора, по которому исполнение должно иметь место или имело место на территории Российской Федерации;\n\n4) требование возникло из причинения вреда имуществу действием или иным обстоятельством, имевшими место на территории Российской Федерации или при наступлении вреда на территории Российской Федерации;\n\n5) спор возник из неосновательного обогащения, имевшего место на территории Российской Федерации;\n\n6) истец по делу о защите деловой репутации находится в Российской Федерации;\n\n7) спор возник из отношений, связанных с обращением ценных бумаг, выпуск которых имел место на территории Российской Федерации;\n\n8) заявитель по делу об установлении факта, имеющего юридическое значение, указывает на наличие этого факта на территории Российской Федерации;\n\n9) спор возник из отношений, связанных с государственной регистрацией имен и других объектов и оказанием услуг в международной ассоциации информационно-телекоммуникационных сетей \"Интернет\" на территории Российской Федерации; (В редакции Федерального закона от 11.07.2011 № 200-ФЗ)\n\n10) в других случаях при наличии тесной связи спорного правоотношения с территорией Российской Федерации.","article_title":"Статья 247. Компетенция арбитражных судов в Российской Федерации по делам с участием иностранных лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"5df1a1ca11f2f9576ed3bd740e822b2b5f4db955e45c02b945d4b43926aba049"},{"code_id":"APK_RF","article_number":"248","version_date":"2002-07-24","article_text":"1. К исключительной компетенции арбитражных судов в Российской Федерации по делам с участием иностранных лиц относятся дела:\n\n1) по спорам в отношении находящегося в государственной собственности Российской Федерации имущества, в том числе по спорам, связанным с приватизацией государственного имущества и принудительным отчуждением имущества для государственных нужд;\n\n2) по спорам, предметом которых являются недвижимое имущество, если такое имущество находится на территории Российской Федерации, или права на него;\n\n3) по спорам, связанным с регистрацией или выдачей патентов, регистрацией и выдачей свидетельств на товарные знаки, промышленные образцы, полезные модели или регистрацией других прав на результаты интеллектуальной деятельности, которые требуют регистрации или выдачи патента либо свидетельства в Российской Федерации;\n\n4) по спорам о признании недействительными записей в государственные реестры (регистры, кадастры), произведенных компетентным органом Российской Федерации, ведущим такой реестр (регистр, кадастр);\n\n5) по спорам, связанным с учреждением, ликвидацией или регистрацией на территории Российской Федерации юридических лиц и индивидуальных предпринимателей, а также с оспариванием решений органов этих юридических лиц.\n\n2. В исключительной компетенции арбитражных судов в Российской Федера\n\nции находятся также предусмотренные в разделе III настоящего Кодекса дела с участием иностранных лиц, возникающие из административных и иных публичных правоотношений.","article_title":"Статья 248. Исключительная компетенция арбитражных судов в Российской Федерации по делам с участием иностранных лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"4e4b4e4a746f28603987ea851b550ff1766a3361b1b6f22afcfd2332b91e7a2a"},{"code_id":"APK_RF","article_number":"248.1","version_date":"2002-07-24","article_text":"1. Если иное не установлено международным договором Российской Федерации или соглашением сторон, в соответствии с которыми рассмотрение споров с их участием отнесено к компетенции иностранных судов, международных коммерческих арбитражей, находящихся за пределами территории Российской Федерации, к исключительной компетенции арбитражных судов в Российской Федерации относятся дела:\n\n1) по спорам с участием лиц, в отношении которых применяются меры ограничительного характера иностранным государством, государственным объединением и (или) союзом и (или) государственным (межгосударственным) учреждением иностранного государства или государственного объединения и (или) союза;\n\n2) по спорам одного российского или иностранного лица с другим российским или иностранным лицом, если основанием для таких споров являются ограничительные меры, введенные иностранным государством, государственным объединением и (или) союзом и (или) государственным (межгосударственным) учреждением иностранного государства или государственного объединения и (или) союза в отношении граждан Российской Федерации и российских юридических лиц.\n\n2. В целях настоящей главы к лицам, в отношении которых иностранным государством, государственным объединением и (или) союзом и (или) государственным (межгосударственным) учреждением иностранного государства или государственного объединения и (или) союза применяются меры ограничительного характера, относятся:\n\n1) граждане Российской Федерации, российские юридические лица, в отношении которых иностранным государством, государственным объединением и (или) союзом и (или) государственным (межгосударственным) учреждением иностранного государства или государственного объединения и (или) союза применяются меры ограничительного характера;\n\n2) иностранные юридические лица, в отношении которых иностранным государством, государственным объединением и (или) союзом и (или) государственным (межгосударственным) учреждением иностранного государства или государственного объединения и (или) союза применяются меры ограничительного характера и основанием для применения таких мер являются ограничительные меры, введенные иностранным государством, государственным объединением и (или) союзом и (или) государственным (межгосударственным) учреждением иностранного государства или государственного объединения и (или) союза в отношении граждан Российской Федерации и российских юридических лиц.\n\n3. Лица, указанные в части 2 настоящей статьи, вправе:\n\n1) обратиться за разрешением спора в арбитражный суд субъекта Российской Федерации по месту своего нахождения или месту жительства при условии, что в производстве иностранного суда или международного коммерческого арбитража, находящихся за пределами территории Российской Федерации, отсутствует спор между теми же лицами, о том же предмете и по тем же основаниям;\n\n2) обратиться в порядке, предусмотренном статьей 2482 настоящего Кодекса, с заявлением о запрете инициировать или продолжать разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации.\n\n4. Положения настоящей статьи применяются также в случае, если соглашение сторон, в соответствии с которым рассмотрение споров с их участием отнесено к компетенции иностранного суда и международного коммерческого арбитража, находящихся за пределами территории Российской Федерации, неисполнимо по причине применения в отношении одного из лиц, участвующих в споре, мер ограничительного характера иностранным государством, государственным объединением и (или) союзом и (или) государственным (межгосударственным) учреждением иностранного государства или государственного объединения и (или) союза, создающих такому лицу препятствия в доступе к правосудию.\n\n5. Положения настоящей статьи не препятствуют признанию и приведению в исполнение решения иностранного суда или иностранного арбитражного решения, принятых по иску лица, указанного в части 2 настоящей статьи, либо если это лицо не возражало против рассмотрения с его участием спора иностранным судом, международным коммерческим арбитражем, находящимися за пределами территории Российской Федерации, в том числе не обращалось с заявлением о запрете инициировать или продолжать разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации.\n\n(Дополнение статьей - Федеральный закон от 08.06.2020 № 171-ФЗ)","article_title":"Статья 248.1. Исключительная компетенция арбитражных судов в Российской Федерации по спорам с участием лиц, в отношении которых введены меры ограничительного характера","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"89619448462f5685ffa7c892e03e6cd95ede6e9015a3ac1c4b1aed8b842858a3"},{"code_id":"APK_RF","article_number":"248.2","version_date":"2002-07-24","article_text":"1. Лицо, в отношении которого инициировано разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, по спорам, указанным в статье 2481 настоящего Кодекса, или при наличии доказательств того, что такое разбирательство будет инициировано, вправе обратиться в арбитражный суд субъекта Российской Федерации по месту своего нахождения или месту жительства с заявлением о запрете инициировать или продолжать такое разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, в порядке, установленном настоящей статьей.\n\n2. В заявлении, предусмотренном частью 1 настоящей статьи, должны быть указаны:\n\n1) наименование арбитражного суда, в который подается заявление;\n\n2) наименование заявителя, его адрес или место жительства, а также наименование лица, в отношении которого требуется установить запрет, его адрес или место жительства;\n\n3) сведения о требованиях, которые могут быть предъявлены или уже предъявлены в иностранном суде, международном коммерческом арбитраже;\n\n4) обстоятельства, подтверждающие исключительную компетенцию арбитражных судов в Российской Федерации по рассмотрению спора, в том числе обстоятельства (при их наличии), подтверждающие, что соглашение сторон, в соответствии с которым рассмотрение спора с их участием отнесено к компетенции иностранного суда, международного коммерческого арбитража, находящихся за пределами территории Российской Федерации, не может быть исполнено стороной спора;\n\n5) требование заявителя о запрете инициировать или продолжать разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации;\n\n6) перечень прилагаемых документов.\n\n3. В заявлении, предусмотренном частью 1 настоящей статьи, могут быть также указаны номера телефонов, факсов, адреса электронной почты заявителя и лиц, которые могут инициировать или инициировали разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, а также их представителей.\n\n4. К заявлению, предусмотренному частью 1 настоящей статьи, прилагаются:\n\n1) копии документов, подтверждающих намерение инициировать разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, либо факт начала разбирательства в иностранном суде, международном коммерческом арбитраже, в том числе претензии, требования, иски и иные документы;\n\n2) копии документов, подтверждающих исключительную компетенцию арбитражных судов в Российской Федерации по рассмотрению спора;\n\n3) иные документы, указанные в статье 126 настоящего Кодекса.\n\n5. Заявление, предусмотренное частью 1 настоящей статьи, рассматривается судьей единолично по правилам рассмотрения дела арбитражным судом первой инстанции, предусмотренным настоящим Кодексом, с учетом особенностей, установленных настоящей статьей.\n\n6. Арбитражный суд извещает лиц, участвующих в деле, о времени и месте судебного заседания в порядке, установленном настоящим Кодексом. Неявка указанных лиц, извещенных надлежащим образом о времени и месте судебного заседания, не является препятствием для рассмотрения заявления, предусмотренного частью 1 настоящей статьи.\n\n7. По результатам рассмотрения заявления, предусмотренного частью 1 настоящей статьи, арбитражный суд выносит определение по правилам, установленным главой 20 настоящего Кодекса для вынесения решений.\n\n8. В определении о запрете или об отказе в запрете стороне инициировать или продолжать разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, должны содержаться:\n\n1) наименования заявителя и лица, в отношении которого выносится запрет;\n\n2) сведения о требованиях, которые могут быть предъявлены в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, либо сведения о конкретном разбирательстве в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, в отношении которых устанавливается запрет;\n\n3) указание на удовлетворение заявления о запрете лицу инициировать или продолжать разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, либо на отказ в удовлетворении такого заявления.\n\n9. Определение арбитражного суда по делу о запрете инициировать или продолжать разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, по спорам, указанным в статье 2481 настоящего Кодекса, может быть обжаловано в кассационном порядке в арбитражный суд округа в течение одного месяца со дня вынесения определения.\n\n10. Арбитражный суд на основе принципов справедливости, соразмерности и недопустимости извлечения выгоды из незаконного или недобросовестного поведения по требованию заявителя вправе присудить в его пользу денежную сумму, подлежащую взысканию с лица, в отношении которого вынесен запрет инициировать или продолжать разбирательство в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, на случай неисполнения им судебного акта. Размер подлежащей взысканию арбитражным судом денежной суммы не должен превышать размера исковых требований, предъявленных в иностранном суде, международном коммерческом арбитраже, находящихся за пределами территории Российской Федерации, и понесенных стороной спора судебных расходов.\n\n(Дополнение статьей - Федеральный закон от 08.06.2020 № 171-ФЗ)","article_title":"Статья 248.2. Запрет инициировать или продолжать разбирательство по спорам с участием лиц, в отношении которых введены меры ограничительного характера","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"de43cb8183e021278fbda594cdc308bf387e7401391d5a81d03066903d401098"},{"code_id":"APK_RF","article_number":"249","version_date":"2002-07-24","article_text":"1. В случае, если стороны, хотя бы одна из которых является иностранным лицом, заключили соглашение, в котором определили, что арбитражный суд в Российской Федерации обладает компетенцией по рассмотрению возникшего или могущего возникнуть спора, связанного с осуществлением ими предпринимательской и иной экономической деятельности, арбитражный суд в Российской Федерации будет обладать исключительной компетенцией по рассмотрению данного спора при условии, что такое соглашение не изменяет исключительную компетенцию иностранного суда.\n\n2. Соглашение об определении компетенции должно быть заключено в письменной форме.","article_title":"Статья 249. Соглашение об определении компетенции арбитражных судов в Российской Федерации","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"822279f33f68075e471e834a76a55f8d2348c6952a37761828c4b6000a0f195c"},{"code_id":"APK_RF","article_number":"25","version_date":"2002-07-24","article_text":"1. В случае заявления отвода арбитражный суд заслушивает мнение лиц, участвующих в деле, а также лица, которому заявлен отвод, если отводимый желает дать объяснения.\n\n2. Вопрос об отводе судьи, рассматривающего дело единолично, разрешается тем же судьей.\n\n3. Вопрос об отводе судьи при рассмотрении дела в коллегиальном составе разрешается этим же составом суда большинством голосов в отсутствие судьи, которому заявлен отвод. При равном числе голосов, поданных за отвод и против отвода, судья считается отведенным.\n\nВопрос об отводе, заявленном нескольким судьям или всему рассматривающему дело составу суда, разрешается всеми судьями, рассматривающими дело, простым большинством голосов.\n\n4. Вопрос об отводе помощника судьи, секретаря судебного заседания, эксперта, специалиста, переводчика разрешается составом суда, рассматривающим дело.\n\n5. По результатам рассмотрения вопроса о самоотводе или об отводе выносится определение.\n\n(Статья в редакции Федерального закона от 28.11.2018 № 451-ФЗ)","article_title":"Статья 25. Порядок разрешения заявленного отвода","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8dbb8fb742e71b9f023f2e9eb2cb064683900e25891c8f41a29926c2d3f9daaa"},{"code_id":"APK_RF","article_number":"250","version_date":"2002-07-24","article_text":"По делам с участием иностранных лиц, отнесенным к компетенции арбитражных судов в Российской Федерации в соответствии с главой 32 настоящего Кодекса, арбитражный суд в Российской Федерации может принять обеспечительные меры по правилам главы 8 настоящего Кодекса.","article_title":"Статья 250. Компетенция арбитражных судов в Российской Федерации по применению обеспечительных мер по делам с участием иностранных лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3f159c0864cb97e4d99984b4a90e1b9ca7c70d2f3b0ff885494c7af5bec10497"},{"code_id":"APK_RF","article_number":"251","version_date":"2002-07-24","article_text":"1. Судебный иммунитет международных организаций определяется международным договором Российской Федерации, федеральным законом.\n\n2. Отказ от судебного иммунитета должен быть произведен в порядке, предусмотренном правилами международной организации. В этом случае арбитражный суд рассматривает дело в порядке, установленном настоящим Кодексом.\n\n(Статья в редакции Федерального закона от 29.12.2015 № 393-ФЗ)","article_title":"Статья 251. Судебный иммунитет международных организаций","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c20ee20849217589f660fa627e15ffd761cbc8c844c62ed53f1796a69671c8b2"},{"code_id":"APK_RF","article_number":"253","version_date":"2002-07-24","article_text":"1. Дела с участием иностранных лиц рассматриваются арбитражным судом по правилам настоящего Кодекса с особенностями, предусмотренными настоящей главой, если международным договором Российской Федерации не предусмотрено иное.\n\n2. Дела с участием иностранных лиц, если эти лица или их органы управления, филиалы, представительства либо их представители, уполномоченные на ведение дела, находятся или проживают на территории Российской Федерации, рассматриваются в сроки, установленные настоящим Кодексом.","article_title":"Статья 253. Порядок рассмотрения дел с участием иностранных лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a7cb927f1ab46aea9390aecfac7b9ccf6911bef5f90de25f7c466c5cfb07e1a1"},{"code_id":"APK_RF","article_number":"254","version_date":"2002-07-24","article_text":"1. Иностранные лица пользуются процессуальными правами и несут процессуальные обязанности наравне с российскими организациями и гражданами. Процессуальные льготы предоставляются иностранным лицам, если они предусмотрены международным договором Российской Федерации.\n\nВ случае непредставления таких доказательств арбитражный суд вправе истребовать их по своей инициативе.","article_title":"Статья 254. Процессуальные права и обязанности иностранных лиц","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"54a55db864f33fd2f7635a860dad2b1789133363d2d6147989b906cb6cbbe701"},{"code_id":"APK_RF","article_number":"255","version_date":"2002-07-24","article_text":"1. Документы, выданные, составленные или удостоверенные по установленной форме компетентными органами иностранных государств вне пределов Российской Федерации по нормам иностранного права в отношении российских организаций и граждан или иностранных лиц, принимаются арбитражными судами в Российской Федерации при наличии легализации указанных документов или проставлении апостиля, если иное не установлено международным договором Российской Федерации.\n\n2. Документы, составленные на иностранном языке, при представлении в арбитражный суд в Российской Федерации должны сопровождаться их надлежащим образом заверенным переводом на русский язык.","article_title":"Статья 255. Требования, предъявляемые к документам иностранного происхождения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"02ac110070ec140f2e5393f78025eb6486b07a48d76863475b2d7b6956322e74"},{"code_id":"APK_RF","article_number":"256","version_date":"2002-07-24","article_text":"1. Арбитражный суд исполняет переданные ему в порядке, установленном международным договором Российской Федерации или федеральным законом, поручения иностранных судов и компетентных органов иностранных государств о выполнении отдельных процессуальных действий (вручение повесток и других документов, получение письменных доказательств, производство экспертизы, осмотр на месте и другие).\n\n2. Поручение иностранного суда или компетентного органа иностранного государства не подлежит исполнению, если:\n\n1) исполнение поручения нарушает основополагающие принципы российского права или иным образом противоречит публичному порядку Российской Федерации;\n\n2) исполнение поручения не относится к компетенции арбитражного суда в Российской Федерации;\n\n3) не установлена подлинность документа, содержащего поручение о выполнении отдельных процессуальных действий.\n\n3. Исполнение арбитражным судом поручений о выполнении отдельных процессуальных действий производится в порядке, установленном настоящим Кодексом, если иное не предусмотрено международным договором Российской Федерации.\n\n4. Арбитражные суды могут в порядке, установленном международным договором Российской Федерации или федеральным законом, обращаться к иностранным судам или компетентным органам иностранных государств с поручениями о выполнении отдельных процессуальных действий.\n\n(Дополнение главой - Федеральный закон от 29.12.2015 № 393-ФЗ)","article_title":"Статья 256. Поручения о выполнении отдельных процессуальных действий","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"decb690ad63302ee7c457d55b165b305cc8bc40a090e41afca5e8d903092dbf3"},{"code_id":"APK_RF","article_number":"256.1","version_date":"2002-07-24","article_text":"1. Предъявление в арбитражном суде иска к иностранному государству, привлечение иностранного государства к участию в деле в качестве ответчика или третьего лица, наложение ареста на имущество иностранного государства, находящееся на территории Российской Федерации, принятие в отношении этого имущества иных мер по обеспечению иска, обращение взыскания на это имущество в порядке исполнения решений арбитражного суда, а также рассмотрение заявлений о признании и принудительном исполнении решений иностранных судов в отношении имущества иностранного государства, находящегося на территории Российской Федерации, осуществляется в соответствии с Федеральным законом от 3 ноября 2015 года № 297-ФЗ \"О юрисдикционных иммунитетах иностранного государства и имущества иностранного государства в Российской Федерации\" в порядке, установленном настоящим Кодексом, если иное не предусмотрено международным договором Российской Федерации.\n\n2. Дела с участием иностранного государства рассматриваются по общим правилам искового производства с особенностями, установленными настоящей главой, главами 32 и 33 настоящего Кодекса и другими федеральными законами\n\n. Заявления о признании и принудительном исполнении решений иностранных судов в отношении имущества иностранного государства, находящегося на территории Российской Федерации, рассматриваются в порядке, установленном настоящей главой, главой 31 настоящего Кодекса и другими федеральными законами.\n\n3. Для целей настоящего Кодекса понятие \"иностранное государство\" используется в значении, определяемом Федеральным законом от 3 ноября 2015 года № 297-ФЗ \"О юрисдикционных иммунитетах иностранного государства и имущества иностранного государства в Российской Федерации\".","article_title":"Статья 256.1. Производство по делам с участием иностранного государства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"96efc922387771d212bad95e0fa8cc7d7cee41a5898fa27fe879a3c0049cde5a"},{"code_id":"APK_RF","article_number":"256.10","version_date":"2002-07-24","article_text":"1. Арбитражный суд вправе рассмотреть дело в отсутствие представителя иностранного государства, являющегося ответчиком по делу, в случае его неявки без уважительных причин в судебное заседание при соблюдении следующих условий:\n\n1) иностранное государство в соответствии с требованиями статьи 2566 настоящего Кодекса надлежащим образом извещено о принятии искового заявления к производству, о возбуждении производства по делу, а также о времени и месте судебного заседания;\n\n2) со дня вручения иностранному государству извещения о возбуждении против него дела прошло не менее шести месяцев;\n\n3) иностранным государством не заявлено ходатайство об отложении на разумный срок судебного заседания либо указанное ходатайство мотивированно отклонено судом.\n\n2. По результатам рассмотрения дела в отсутствие иностранного государства, являющегося ответчиком по делу, и при соблюдении всех условий, предусмотренных частью 1 настоящей статьи, арбитражный суд может вынести решение в отсутствие указанного иностранного государства, если установит, что в соответствии с законодательством Российской Федерации иностранное государство не пользуется судебным иммунитетом в отношении рассматриваемого спора. Копия решения арбитражного суда не позднее чем в течение пяти дней со дня его принятия направляется арбитражным судом иностранному государству в порядке, установленном статьей 256 настоящего Кодекса.\n\n3. Иностранное государство в течение двух месяцев со дня вручения ему в порядке, установленном статьей 256 настоящего Кодекса, копии указанного в части 2 настоящей статьи решения арбитражного суда вправе подать в арбитражный суд, принявший такое решение, заявление о его отмене.\n\n4. Решение арбитражного суда, вынесенное по результатам рассмотрения дела в отсутствие иностранного государства, являющегося ответчиком по делу, также может быть обжаловано сторонами в апелляционном порядке в течение месяца после истечения срока подачи ответчиком заявления об отмене этого решения арбитражного суда, а в случае, если такое заявление подано, - в течение двух месяцев со дня вынесения арбитражным судом определения об отказе в удовлетворении этого заявления.","article_title":"Статья 256.10. Рассмотрение дела в отсутствие иностранного государства, являющегося ответчиком","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"93f5190acb1a8d20dfd4f0fd4e5dd038dc12fbca90ca47e6916f26a7c3cf18cd"},{"code_id":"APK_RF","article_number":"256.11","version_date":"2002-07-24","article_text":"1. При рассмотрении арбитражным судом дела с участием иностранного государства на это иностранное государство не может быть наложен судебный штраф, а также к этому иностранному государству не могут быть предъявлены требования о предварительной оплате судебных расходов, связанных с рассмотрением дела.\n\n2. Положения части 1 настоящей статьи не препятствуют арбитражному суду взыскать с иностранного государства судебные расходы по правилам, установленным главой 9 настоящего Кодекса, при принятии арбитражным судом решения по результатам рассмотрения дела по существу.","article_title":"Статья 256.11. Привилегии и иммунитеты иностранного государства в ходе судебного разбирательства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"074ab854155a6187ec42d5577b7ba81e123bdf714d4121b84233a3b3e29376d7"},{"code_id":"APK_RF","article_number":"256.12","version_date":"2002-07-24","article_text":"Исполнение судебных актов арбитражного суда, вынесенных в отношении иностранного государства, его имущества, находящегося на территории Российской Федерации, по результатам рассмотрения соответствующих иска или заявления о признании и исполнении судебных решений другого иностранного государства, осуществляется в соответствии с законодательством Российской Федерации об исполнительном производстве. Исполнительный лист с копией судебного акта арбитражного суда направляется главному судебному приставу Российской Федерации. Одновременно арбитражный суд в порядке, установленном статьей 2566 настоящего Кодекса, извещает иностранное государство о вступлении судебного акта в законную силу и направлении исполнительных документов главному судебному приставу Российской Федерации для исполнения.\n\nРАЗДЕЛ VI. ПРОИЗВОДСТВО ПО ПЕРЕСМОТРУ СУДЕБНЫХ АКТОВ АРБИТРАЖНЫХ СУДОВ","article_title":"Статья 256.12. Порядок исполнения судебных актов арбитражного суда в отношении иностранного государства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"8c179284449c81977d6a5e817707645cab975454b9b46e05b1f0190826cfc5e3"},{"code_id":"APK_RF","article_number":"256.2","version_date":"2002-07-24","article_text":"Компетенция судов Российской Федерации по рассмотрению дел с участием иностранного государства определяется по правилам, установленным главой 4 настоящего Кодекса.\n\n(Статья в редакции Федерального закона от 28.11.2018 № 451-ФЗ)","article_title":"Статья 256.2. Компетенция арбитражных судов по делам с участием иностранного государства","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"311d28362c90e67be9b6ec8e99e6889a3febe3059f29cd3322236bacd6f342bc"},{"code_id":"APK_RF","article_number":"256.3","version_date":"2002-07-24","article_text":"1. Иностранное государство пользуется в отношении себя и своего имущества, находящегося на территории Российской Федерации, юрисдикционными иммунитетами с учетом положений Федерального закона от 3 ноября 2015 года № 297-ФЗ \"О юрисдикционных иммунитетах иностранного государства и имущества иностранного государства в Российской Федерации\".\n\n2. Иностранное государство пользуется процессуальными правами и выполняет процессуальные обязанности наравне с российскими гражданами и организациями, в том числе правом вести свои дела в суде через представителей. Полномочия представителя иностранного государства должны быть выражены в доверенности или ином соответствующем документе, выданном представляемым иностранным государством и оформленном в соответствии с законодательством Российской Федерации или законодательством иностранного государства, с учетом требований, предусмотренных статьей 255 настоящего Кодекса.\n\n3. Представитель иностранного государства вправе совершать от имени представляемого им иностранного государства все процессуальные действия, за исключением действий, указанных в части 4 настоящей статьи, если иное не предусмотрено в доверенности или ином соответствующем документе, выданном представляемым иностранным государством.\n\n4. В доверенности или ином соответствующем документе, выданном представляемым иностранным государством, должно быть специально оговорено право представителя этого иностранного государства на подписание отзыва на исковое заявление, признание иска, отказа от судебного иммунитета, иммунитета в отношении мер по обеспечению иска, иммунитета в отношении исполнения судебного решения, предъявление встречного иска, изменение основания или предмета встречного иска, заключение мирового соглашения и соглашения по фактическим обстоятельствам, передачу своих полномочий представителя другому лицу (передоверие), получение судебных извещений (включая копии судебных актов), обжалование судебных актов, подписание, подачу заявления о пересмотре судебных актов по новым или вновь открывшимся обстоятельствам, а также на получение присужденных денежных средств или иного имущества.","article_title":"Статья 256.3. Юрисдикционные иммунитеты, процессуальные права и обязанности иностранного государства, представительство","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"24ad692e4146097559688831051c6c184464eee7e846f06cdae6280810c8a2b4"},{"code_id":"APK_RF","article_number":"256.4","version_date":"2002-07-24","article_text":"1. Исковое заявление по спору с иностранным государством и прилагаемые к нему документы должны соответствовать требованиям статей 125 и 126 настоящего Кодекса и подаются в арбитражный суд с копиями искового заявления и прилагаемых к нему документов в соответствии с количеством ответчиков и третьих лиц.\n\n2. К исковому заявлению также прилагается надлежащим образом заверенный перевод искового заявления и прилагаемых к нему документов на официальный язык или один из официальных языков иностранного государства, привлекаемого к участию в деле.","article_title":"Статья 256.4. Подача искового заявления","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"6ea5a9ad1e792ce664b6f071a00bb2b47ad1af09ba5f792554128842e7a1621e"},{"code_id":"APK_RF","article_number":"256.5","version_date":"2002-07-24","article_text":"1. Меры по обеспечению иска применяются арбитражным судом по заявлению лиц, участвующих в деле, в порядке, установленном главой 8 настоящего Кодекса, за исключением случаев, если иностранное государство и его имущество, находящееся на территории Российской Федерации, пользуются иммунитетом в отношении мер по обеспечению иска и иностранное государство не отказалось от этого иммунитета.\n\n2. Примененные арбитражным судом меры по обеспечению иска подлежат отмене, если в ходе судебного разбирательства будет установлено, что иностранное государство и его имущество, находящееся на территории Российской Федерации, пользуются иммунитетом в отношении мер по обеспечению иска или иммунитетом в отношении исполнения судебного решения и иностранное государство не отказалось от этих иммунитетов.","article_title":"Статья 256.5. Особенности применения мер по обеспечению иска","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bece0210f1fc999f16fcb3ce664b9f273496ec542abdbdc70d7b6a9b5b75ba22"},{"code_id":"APK_RF","article_number":"256.6","version_date":"2002-07-24","article_text":"1. Направление иностранному государству судебного извещения о возбуждении против него дела в суде Российской Федерации, а также иного процессуального документа, подлежащего вручению иностранному государству (далее - судебное извещение), осуществляется арбитражным судом в соответствии с применимым международным договором Российской Федерации.\n\n2. В случае отсутствия применимого международного договора Российской Федерации арбитражный суд направляет судебное извещение в федеральный орган исполнительной власти, уполномоченный в области юстиции, для последующего направления (вручения) иностранному государству по дипломатическим каналам через федеральный орган исполнительной власти, осуществляющий функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере международных отношений Российской Федерации.\n\n3. Заверенная копия дипломатической ноты, препровождающей направление судебного извещения иностранному государству, с указанием даты ее получения компетентным органом иностранного государства, ведающим вопросами иностранных дел, направляется в арбитражный суд, направивший извещение. Дата получения указанной дипломатической ноты компетентным органом иностранного государства, ведающим вопросами иностранных дел, считается датой вручения судебного извещения.\n\n4. Поступившие в Российскую Федерацию от иностранного государства по дипломатическим каналам отзыв, заявление, ходатайство и иные документы, касающиеся предъявленного к этому иностранному государству иска, направляются федеральным органом исполнительной власти, уполномоченным в области юстиции, в арбитражный суд, в производстве которого находится дело по иску к указанному иностранному государству.\n\n5. Указанные в частях 1 - 3 настоящей статьи судебные извещения могут быть вручены арбитражным судом непосредственно под расписку представителю иностранного государства, если он участвует в деле и в установленном порядке наделен соответствующими полномочиями.\n\n6. Судебные извещения о назначении предварительного судебного заседания или о назначении дела к разбирательству в судебном заседании направляются иностранному государству в порядке, установленном настоящей статьей, не позднее чем за шесть месяцев до дня судебного заседания.\n\n7. Судебные извещения, подлежащие вручению иностранному государству, составляются в двух экземплярах, заверяются судом и сопровождаются надлежащим образом заверенным переводом на официальный язык или один из официальных языков иностранного государства, привлекаемого к участию в деле.","article_title":"Статья 256.6. Направление и вручение иностранному государству извещений и иных процессуальных документов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"22695dd3199d5b3924d3168155f7717611540920fcfaef17a34c433be98cf1af"},{"code_id":"APK_RF","article_number":"256.7","version_date":"2002-07-24","article_text":"1. В предварительном судебном заседании, проводимом в соответствии со статьей 136 настоящего Кодекса, арбитражный суд с участием сторон также решает вопрос о наличии у иностранного государства судебного иммунитета в отношении рассматриваемого спора.\n\n2. В случае неявки надлежащим образом извещенного о дате, времени и месте предварительного судебного заседания представителя иностранного государства суд принимает решение на основе материалов, имеющихся в деле.\n\n3. Если имеющиеся в деле материалы не позволяют арбитражному суду в предварительном судебном заседании сделать вывод о наличии у иностранного государства судебного иммунитета в отношении рассматриваемого спора, этот вопрос подлежит разрешению при разбирательстве в судебном заседании при рассмотрении дела.\n\n4. Установленные арбитражным судом обстоятельства и вывод арбитражного суда о наличии или отсутствии у иностранного государства судебного иммунитета, иммунитета в отношении мер по обеспечению иска и иммунитета в отношении исполнения решения суда должны быть отражены в судебном акте, принимаемом по результатам рассмотрения дела.\n\n5. В случае, если суд в предварительном судебном заседании или при разбирательстве в судебном заседании пришел к выводу о наличии у иностранного государства судебного иммунитета, суд прекращает производство по делу в отношении его.","article_title":"Статья 256.7. Особенности предварительного судебного заседания и прекращения производства по делу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"16c94f03b893b1bceeb3abbb29482a0ae4bebbd5fb6aa7439c6fa8f989188423"},{"code_id":"APK_RF","article_number":"256.8","version_date":"2002-07-24","article_text":"1. Федеральный орган исполнительной власти, осуществляющий функции по выработке и реализации государственной политики и нормативно-правовому регулированию в сфере международных отношений Российской Федерации, по инициативе суда или по собственной инициативе может участвовать в деле для дачи заключения по вопросам предоставления юрисдикционных иммунитетов Российской Федерации и ее имуществу в иностранном государстве.\n\n2. Заключение указанного в части 1 настоящей статьи федерального органа исполнительной власти может быть получено по вопросам о статусе образования, органа, организации, должностного лица, привлекаемых к участию в деле в качестве иностранного государства, о наличии судебного иммунитета в отношении рассматриваемого спора, иммунитета имущества иностранного государства, находящегося на территории Российской Федерации и являющегося предметом спора, иммунитета в отношении мер по обеспечению иска и иммунитета в отношении исполнения решения суда, о юрисдикционных иммунитетах, предоставляемых Российской Федерации в иностранном государстве, и их объеме, а также по иным вопросам, относящимся к компетенции указанного государственного органа.\n\n3. Заключение указанного в части 1 настоящей статьи федерального органа исполнительной власти подлежит оценке судом по установленным настоящим Кодексом правилам оценки доказательств.","article_title":"Статья 256.8. Участие в деле государственных органов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"ddd185007ed5d8d8be6b191260440e48105a3c036217e216f51b29b44f4fb53c"},{"code_id":"APK_RF","article_number":"256.9","version_date":"2002-07-24","article_text":"1. При рассмотрении иска арбитражный суд по собственной инициативе или по ходатайству стороны в соответствии с Федеральным законом от 3 ноября 2015 года № 297-ФЗ \"О юрисдикционных иммунитетах иностранного государства и имущества иностранного государства в Российской Федерации\" может применить принцип взаимности, если в ходе судебного разбирательства будет установлено, что объем юрисдикционных иммунитетов, предоставляемых Российской Федерации в иностранном государстве, не соответствует объему юрисдикционных иммунитетов, предоставляемых этому иностранному государству в соответствии с законодательством Российской Федерации при разрешении конкретного спора.\n\n2. Соотношение объема юрисдикционных иммунитетов, предоставляемых Российской Федерации в иностранном государстве, и юрисдикционных иммунитетов иностранного государства в Российской Федерации определяется арбитражным судом на основании доказательств, представленных сторонами, и заключений государственных органов.\n\n3. Мотивированное решение арбитражного суда о применении принципа взаимности и в соответствии с ним ограничении юрисдикционных иммунитетов иностранного государства при рассмотрении конкретного дела указывается в решении арбитражного суда, принимаемом по итогам рассмотрения этого дела.","article_title":"Статья 256.9. Применение принципа взаимности","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"866a3983605c7cef57cb02c183bd30dc95263e6457e0276e79bdb6ab49106347"},{"code_id":"APK_RF","article_number":"257","version_date":"2002-07-24","article_text":"1. Лица, участвующие в деле, а также иные лица в случаях, предусмотренных настоящим Кодексом, вправе обжаловать в порядке апелляционного производства решение арбитражного суда первой инстанции, не вступившее в законную силу.","article_title":"Статья 257. Право апелляционного обжалования","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"77de8803ff56fd30fced12be2b30f9901406bb28e472c1f69eede4a623ae6eb0"},{"code_id":"APK_RF","article_number":"258","version_date":"2002-07-24","article_text":"Апелляционные жалобы рассматривает в порядке апелляционного производства арбитражный суд апелляционной инстанции, образованный в соответствии с Федеральным конституционным законом \"Об арбитражных судах в Российской Федерации\".","article_title":"Статья 258. Арбитражный суд апелляционной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"17969d1308607b0181b28a9471b035d901c7f7cadaa1dffc01f18e9f1be24cc4"},{"code_id":"APK_RF","article_number":"259","version_date":"2002-07-24","article_text":"1. Апелляционная жалоба может быть подана в течение месяца после принятия арбитражным судом первой инстанции обжалуемого решения, если иной срок не установлен настоящим Кодексом.","article_title":"Статья 259. Срок подачи апелляционной жалобы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"c58567a0bdec3495f012993b814187288dd4fd61ca81d6275ccebb2ad13d21f7"},{"code_id":"APK_RF","article_number":"26","version_date":"2002-07-24","article_text":"1. Судья, заявивший самоотвод, а также судья, в отношении которого удовлетворено заявление об отводе, заменяется другим судьей.\n\n2. В случае удовлетворения заявления о самоотводе или об отводе судьи, либо нескольких судей, либо всего состава суда дело рассматривается в том же арбитражном суде, но в ином составе судей.\n\n3. Если в результате удовлетворения самоотводов и отводов невозможно сформировать новый состав суда для рассмотрения данного дела в том же арбитражном суде, дело передается в другой арбитражный суд того же уровня в порядке, установленном статьей 39 настоящего Кодекса.\n\n(Обозначение и наименование параграфа исключены - Федеральный закон от 28.11.2018 № 451-ФЗ)","article_title":"Статья 26. Последствия удовлетворения заявления об отводе","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"cc084e56f4067ab0bdfe791e2548eafce2d2b8070527486b3ef9258f76ede208"},{"code_id":"APK_RF","article_number":"260","version_date":"2002-07-24","article_text":"1. Апелляционная жалоба может быть подана в арбитражный суд на бумажном носителе или в электронном виде, в том числе в форме электронного документа. Апелляционная жалоба подписывается лицом, подающим жалобу, или его представителем, уполномоченным на подписание жалобы.\n\nАпелляционная жалоба, подаваемая в электронном виде, содержащая ходатайство об обеспечении иска, должна быть подписана усиленной квалифицированной электронной подписью.\n\n(Часть в редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n2. В апелляционной жалобе должны быть указаны:\n\n1) наименование арбитражного суда, в который подается апелляционная жалоба;\n\n2) наименование лица, подающего жалобу, и других лиц, участвующих в деле;\n\n3) наименование арбитражного суда, принявшего обжалуемое решение, номер дела и дата принятия решения, предмет спора;\n\n4) требования лица, подающего жалобу, и основания, по которым лицо, подающее жалобу, обжалует решение, со ссылкой на законы, иные нормативные правовые акты, обстоятельства дела и имеющиеся в деле доказательства;\n\n5) перечень прилагаемых к жалобе документов.\n\nВ апелляционной жалобе могут быть указаны номера телефонов, факсов, адреса электронной почты и иные необходимые для рассмотрения дела сведения, а также заявлены имеющиеся ходатайства.\n\n3. Лицо, подающее апелляционную жалобу, обязано направить другим лицам, участвующим в деле, копии апелляционн\n\nой жалобы и прилагаемых к ней документов, которые у них отсутствуют, заказным письмом с уведомлением о вручении либо вручить их другим лицам, участвующим в деле, или их представителям лично под расписку.\n\nАпелляционная жалоба и прилагаемые к ней документы в электронном виде направляются лицам, участвующим в деле, посредством единого портала государственных и муниципальных услуг либо системы электронного документооборота участника арбитражного процесса с использованием единой системы межведомственного электронного взаимодействия. (Дополнение абзацем - Федеральный закон от 30.12.2021 № 440-ФЗ)\n\n4. К апелляционной жалобе прилагаются:\n\n1) копия оспариваемого решения;\n\n2) документы, подтверждающие уплату государственной пошлины в установленных порядке и размере или право на получение льготы по уплате государственной пошлины, либо ходатайство о предоставлении отсрочки, рассрочки ее уплаты или об уменьшении размера государственной пошлины;\n\n3) документ, подтверждающий направление или вручение другим лицам, участвующим в деле, копий апелляционной жалобы и документов, которые у них отсутствуют;\n\n4) доверенность или иной документ, подтверждающие полномочия на подписание апелляционной жалобы, а также копии документов о высшем юридическом образовании или об ученой степени по юридической специальности представителя, подписавшего апелляционную жалобу, либо документов, удостоверяющих его статус адвоката, патентного поверенного, арбитражного управляющего, единоличного органа управления организации. (В редакции  Федерального закона от 25.12.2023 № 667-ФЗ)\n\nК апелляционной жалобе на определение арбитражного суда о возвращении искового заявления должны быть также приложены возвращенное исковое заявление и документы, прилагавшиеся к нему при подаче в арбитражный суд. Документы, прилагаемые к апелляционной жалобе, могут быть представлены в арбитражный суд в электронном виде. (В редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 260. Форма и содержание апелляционной жалобы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3a49b8b70d002d355c4f8cde4ea0ebc463d2601f2017d1c363e0143885020c3c"},{"code_id":"APK_RF","article_number":"261","version_date":"2002-07-24","article_text":"1. Апелляционная жалоба, поданная с соблюдением требований, предъявляемых настоящим Кодексом к ее форме и содержанию, принимается к производству арбитражного суда апелляционной инстанции. В случае нарушения указанных требований арбитражный суд или оставляет жалобу без движения, или возвращает ее в порядке, предусмотренном в статьях 263 и 264 настоящего Кодекса.\n\n2. Вопрос о принятии апелляционной жалобы к производству решается судьей арбитражного суда апелляционной инстанции единолично в пятидневный срок со дня ее поступления в арбитражный суд апелляционной инстанции.\n\nО принятии апелляционной жалобы арбитражный суд апелляционной инстанции выносит определение, которым возбуждается производство по апелляционной жалобе.\n\nВ определении указываются время и место проведения судебного заседания по рассмотрению апелляционной жалобы. При этом время проведения первого судебного заседания по рассмотрению апелляционной жалобы определяется с учетом того, что оно не может быть назначено ранее истечения срока, установленного настоящим Кодексом для обжалования соответствующего решения арбитражного суда. (В редакции Федерального закона от 27.07.2010 № 228-ФЗ)","article_title":"Статья 261. Принятие апелляционной жалобы к производству арбитражного суда","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9c69256f7cf481c94f78b243c28ba5c03fa7e133bc931a788de20ebd7ed19648"},{"code_id":"APK_RF","article_number":"262","version_date":"2002-07-24","article_text":"1. Лицо, участвующее в деле, направляет отзыв на апелляционную жалобу с приложением документов, подтверждающих возражения относительно жалобы, другим лицам, участвующим в деле, и в арбитражный суд.\n\nК отзыву, направляемому в арбитражный суд, прилагается также документ, подтверждающий направление отзыва другим лицам, участвующим в деле.","article_title":"Статья 262. Отзыв на апелляционную жалобу","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"a6ed791d69b5321994d73cfb1894535b2bf83aab45a02a9e999800cf0a21b8ce"},{"code_id":"APK_RF","article_number":"263","version_date":"2002-07-24","article_text":"1. Арбитражный суд апелляционной инстанции, установив при рассмотрении вопроса о принятии апелляционной жалобы к производству, что она подана с нарушением требований, установленных статьей 260 настоящего Кодекса, выносит определение об оставлении апелляционной жалобы без движения.\n\nАбзац. (Утратил силу - Федеральный закон от 25.12.2023 № 667-ФЗ)\n\n2. В определении арбитражный суд указывает основания для оставления апелляционной жалобы без движения и срок, в течение которого лицо, подавшее апелляционную жалобу, должно устранить обстоятельства, послужившие основанием для оставления апелляционной жалобы без движения.\n\n3. Копия определения об оставлении апелляционной жалобы без движения направляется лицу, подавшему апелляционную жалобу, не позднее следующего дня после дня его вынесения.\n\n4. В случае, если обстоятельства, послужившие основанием для оставления апелляционной жалобы без движения, будут устранены в срок, указанный в определении суда, апелляционная жалоба считается поданной в день ее первоначального поступления в суд и принимается к производству арбитражного суда апелляционной инстанции.\n\n5. В случае, если указанные обстоятельства не будут устранены в срок, указанный в определении, арбитражный суд возвращает апелляционную жалобу и прилагаемые к ней документы лицу, подавшему жалобу, в порядке, установленном статьей 264 настоящего Кодекса.","article_title":"Статья 263. Оставление апелляционной жалобы без движения","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"9c561e425eeb0b46389a46be9d644edd03ae2cdbf1e5b38f8c652bcc8a0c4dc6"},{"code_id":"APK_RF","article_number":"264","version_date":"2002-07-24","article_text":"1. Арбитражный суд апелляционной инстанции возвращает апелляционную жалобу, если при рассмотрении вопроса о принятии апелляционной жалобы к производству установит, что:\n\n1) апелляционная жалоба подана лицом, не имеющим права на обжалование судебного акта в порядке апелляционного производства;\n\n11) апелляционная жалоба не подписана или апелляционная жалоба подписана  лицом, не имеющим полномочий на ее подписание; (Дополнение пунктом - Федеральный закон от 28.11.2018 № 451-ФЗ) (В редакции Федерального закона от 02.12.2019 № 406-ФЗ)\n\n2) апелляционная жалоба подана на судебный акт, который в соответствии с настоящим Кодексом не обжалуется в порядке апелляционного производства;\n\n3) апелляционная жалоба подана по истечении срока подачи апелляционной жалобы, установленного в настоящем Кодексе, и не содержит ходатайство о его восстановлении или в восстановлении пропущенного срока на подачу апелляционной жалобы отказано;\n\n4) до вынесения определения о принятии апелляционной жалобы к производству суда от лица, подавшего жалобу, поступило ходатайство о ее возвращении;\n\n5) не устранены обстоятельства, послужившие основанием для оставления жалобы без движения, в срок, установленный в определении суда.\n\nАрбитражный суд апелляционной инстанции также возвращает жалобу, если отклонено ходатайство о предоставлении отсрочки, рассрочки уплаты государственной пошлины или об уменьшении ее размера.\n\n2. О возвращении апелляционной жалобы арбитражный суд выносит определение.\n\n3. В определении указываются основания для возвращения апелляционной жалобы, решается вопрос о возврате государственной пошлины из федерального бюджета.\n\nКопия определения о возвращении апелляционной жалобы направляется лицу, подавшему жалобу, вместе с жалобой и прилагаемыми документами не позднее следующего дня после дня его вынесения или после истечения срока, установленного судом для устранения обстоятельств, послуживших основанием для оставления апелляционной жалобы без движения.\n\n4. Определение арбитражного суда о возвращении апелляционной жалобы может быть обжаловано.\n\nВ случае отмены определения апелляционная жалоба считается поданной в день первоначального обращения в арбитражный суд.\n\n5. Возвращение апелляционной жалобы не препятствует повторному обращению с апелляционной жалобой в арбитражный суд в общем порядке после устранения обстоятельств, послуживших основанием для ее возвращения.","article_title":"Статья 264. Возвращение апелляционной жалобы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"bdd3aa9798701d56aab9d107dd33a54639707b68dc4d2aa2f8888cfd1bbcbd27"},{"code_id":"APK_RF","article_number":"265","version_date":"2002-07-24","article_text":"1. Арбитражный суд апелляционной инстанции прекращает производство по апелляционной жалобе, если от лица, ее подавшего, после принятия апелляционной жалобы к производству арбитражного суда поступило ходатайство об отказе от апелляционной жалобы и отказ был принят арбитражным судом в соответствии со статьей 49 настоящего Кодекса.\n\n2. В случае, если в апелляционной жалобе заявлены новые требования, которые не были предметом рассмотрения в арбитражном суде первой инстанции, принявшем обжалуемое решение, арбитражный суд апелляционной инстанции прекращает производство по апелляционной жалобе в части этих требований.\n\n3. О прекращении производства по апелляционной жалобе арбитражный суд выносит определение.\n\nКопии определения о прекращении производства по апелляционной жалобе направляются лицам, участвующим в деле, не позднее следующего дня после дня его вынесения.\n\n4. Определение арбитражного суда о прекращении производства по апелляционной жалобе может быть обжаловано.\n\n5. В случае прекращения производства по апелляционной жалобе повторное обращение того же лица по тем же основаниям в арбитражный суд с апелляционной жалобой не допускается.","article_title":"Статья 265. Прекращение производства по апелляционной жалобе","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"edbb7abf24c376eef0b5bd522c949ecc4ba9c2ea06c8282cfb8d5cfccf3b6587"},{"code_id":"APK_RF","article_number":"265.1","version_date":"2002-07-24","article_text":"1. Арбитражный суд апелляционной инстанции по ходатайству лиц, участвующих в деле, вправе приостановить исполнение судебных актов, принятых арбитражным судом первой инстанции, при условии, если заявитель обосновал невозможность или затруднительность поворота исполнения либо предоставил обеспечение, предусмотренное в части 2 настоящей статьи.\n\nХодатайство о приостановлении исполнения судебных актов, подаваемое в электронном виде, должно быть подписано усиленной квалифицированной электронной подписью. (Дополнение абзацем - Федеральный закон от 23.06.2016 № 220-ФЗ) (В редакции Федерального закона от 30.12.2021 № 440-ФЗ)\n\n2. Исполнение решения арбитражного суда приостанавливается арбитражным судом апелляционной инстанции при предоставлении лицом, ходатайствующим о таком приостановлении, обеспечения возмещения другой стороне по делу возможных убытков (встречного обеспечения) путем внесения на депозитный счет арбитражного суда апелляционной инстанции денежных средств в размере оспариваемой суммы либо предоставления банковской гарантии, поручительства или иного финансового обеспечения на ту же сумму.\n\n3. О приостановлении исполнения судебного акта или об отказе в приостановлении исполнения арбитражный суд апелляционной инстанции выносит определение в трехдневный срок со дня поступления ходатайства в суд. Определение может быть обжаловано в арбитражный суд кассационной инстанции. Содержание этого определения может быть изложено в определении о принятии апелляционной жалобы к производству суда.\n\nКопия определения направляется лицам, участвующим в деле.\n\n4. Исполнение судебного акта приостанавливается на срок до принятия арбитражным судом апелляционной инстанции постановления по результатам рассмотрения апелляционной жалобы, если судом не установлен иной срок приостановления.\n\n(Дополнение статьей - Федеральный закон от 25.06.2012 № 86-ФЗ)","article_title":"Статья 265.1. Приостановление исполнения судебных актов арбитражным судом апелляционной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"146ba21e4ca650aefcf7cac50a0751cec3797ca857d1c774759d26aab00f0090"},{"code_id":"APK_RF","article_number":"267","version_date":"2002-07-24","article_text":"(Статья в редакции Федерального закона от 30.04.2010 № 69-ФЗ)","article_title":"Статья 267. Срок рассмотрения апелляционной жалобы","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"3719fd3804ca9e264fffb5107da372c727e94e80dbaef9c4f409dfde93141e50"},{"code_id":"APK_RF","article_number":"268","version_date":"2002-07-24","article_text":"1. При рассмотрении дела в порядке апелляционного производства арбитражный суд по имеющимся в деле и дополнительно представленным доказательствам повторно рассматривает дело.\n\nДокументы, представленные для обоснования возражений относительно апелляционной жалобы в соответствии со статьей 262 настоящего Кодекса, принимаются и рассматриваются арбитражным судом апелляционной инстанции по существу.\n\nНа отмену решения арбитражного суда первой инстанции указывается в постановлении, принимаемом арбитражным судом апелляционной инстанции по результатам рассмотрения апелляционной жалобы. (Дополнение абзацем - Федеральный закон от 27.07.2010 № 228-ФЗ)\n\n(Дополнение частью - Федеральный закон от 30.04.2010 № 69-ФЗ)","article_title":"Статья 268. Пределы рассмотрения дела арбитражным судом апелляционной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"25f4cf609512a1ec1680c9e1a0f30b96046f2c7024bb9cbccff1bdb7252b19b4"},{"code_id":"APK_RF","article_number":"269","version_date":"2002-07-24","article_text":"По результатам рассмотрения апелляционной жалобы арбитражный суд апелляционной инстанции вправе:\n\n1) оставить решение арбитражного суда первой инстанции без изменения, а апелляционную жалобу - без удовлетворения;\n\n2) отменить или изменить решение суда первой инстанции полностью или в части и принять по делу новый судебный акт;\n\n3) отменить решение полностью или в части и прекратить производство по делу либо оставить исковое заявление без рассмотрения полностью или в части.","article_title":"Статья 269. Полномочия арбитражного суда апелляционной инстанции","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"0bc533835f05450d62124807010094b838788e1215438d2936149a878c1772bf"},{"code_id":"APK_RF","article_number":"27","version_date":"2002-07-24","article_text":"(Наименование в редакции Федерального закона от 28.11.2018 № 451-ФЗ)\n\n1) о несостоятельности (банкротстве);\n\n2) по спорам, указанным в статье 2251 настоящего Кодекса;\n\n3) по спорам об отказе в государственной регистрации, уклонении от государственной регистрации юридических лиц, индивидуальных предпринимателей;\n\n4) по спорам, вытекающим из деятельности депозитариев, связанной с учетом прав на акции и иные ценные бумаги и с осуществлением предусмотренных федеральным законом иных прав и обязанностей;\n\n5) по спорам, вытекающим из деятельности публично-правовых компаний, государственных компаний, государственных корпораций и связанным с их правовым положением, порядком управления ими, их созданием, реорганизацией, ликвидацией, организацией и с полномочиями их органов, ответственностью лиц, входящих в их органы;\n\n6) по спорам о защите интеллектуальных прав с участием организаций, осуществляющих коллективное управление авторскими и смежными правами, а также по спорам, отнесенным к подсудности Суда по интеллектуальным правам в соответствии с частью 4 статьи 34 настоящего Кодекса;\n\n7) о защите деловой репутации в сфере предпринимательской и иной экономической деятельности;\n\n71) по спорам, указанным в статье 2481 настоящего Кодекса; (Дополнение пунктом - Федеральный закон от 08.06.2020 № 171-ФЗ)\n\n8) другие дела, возникающие при осуществлении предпринимательской и иной экономической деятельности, в случаях, предусмотренных федеральным законом.\n\n(Дополнение частью - Федеральный закон от 29.12.2015 № 409-ФЗ)","article_title":"Статья 27. Споры, относящиеся к компетенции арбитражных судов","amendment_eo_number":"95-ФЗ","amendment_date":"2002-07-24","is_current":true,"is_repealed":false,"repealed_date":null,"text_hash":"75a6172107a85f44042fe303739d3aa08eca6112946b87bd36495b2c9fa254c6"}]$law7d0006$::jsonb) as x(code_id text,article_number text,version_date date,article_text text,article_title text,amendment_eo_number text,amendment_date date,is_current boolean,is_repealed boolean,repealed_date date,text_hash text))
insert into law7_mirror.article_versions(code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,source_commit,imported_at)
select code_id,article_number,version_date,article_text,article_title,amendment_eo_number,amendment_date,is_current,is_repealed,repealed_date,text_hash,'70a1d8fc6b27b67ad7f12f03f017d02b5f68a0c895447159039800965895f8b2',now() from j
on conflict (code_id,article_number,version_date) do update set article_text=excluded.article_text,article_title=excluded.article_title,amendment_eo_number=excluded.amendment_eo_number,amendment_date=excluded.amendment_date,is_current=excluded.is_current,is_repealed=excluded.is_repealed,repealed_date=excluded.repealed_date,text_hash=excluded.text_hash,source_commit=excluded.source_commit,imported_at=now();
commit;
